import { useRef, type KeyboardEvent, type PointerEvent } from "react";

const KEY_STEP = 16;

type ResizeHandleProps = {
  width: number;
  minSize: number;
  maxSize: number;
  onResize(width: number): void;
  onCommit(): void;
  onReset(): void;
  label: string;
};

/**
 * Drag/keyboard handle on a header cell's right edge. The header cell must be
 * `relative` and carry `group/header`; the handle stays invisible until that
 * header is hovered or the handle has keyboard focus.
 */
export function ResizeHandle({
  width,
  minSize,
  maxSize,
  onResize,
  onCommit,
  onReset,
  label,
}: ResizeHandleProps) {
  const drag = useRef<{ pointerId: number; startX: number; startWidth: number } | null>(null);

  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return;
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.setPointerCapture(event.pointerId);
    drag.current = { pointerId: event.pointerId, startX: event.clientX, startWidth: width };
  };

  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d || d.pointerId !== event.pointerId) return;
    onResize(d.startWidth + (event.clientX - d.startX));
  };

  const endDrag = (event: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d || d.pointerId !== event.pointerId) return;
    drag.current = null;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    onCommit();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
      event.preventDefault();
      onResize(width + (event.key === "ArrowLeft" ? -KEY_STEP : KEY_STEP));
      onCommit();
    } else if (event.key === "Enter") {
      event.preventDefault();
      onReset();
    }
  };

  return (
    <div
      role="separator"
      aria-orientation="vertical"
      aria-valuenow={width}
      aria-valuemin={minSize}
      aria-valuemax={maxSize}
      aria-label={`Resize ${label}`}
      tabIndex={0}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={endDrag}
      onPointerCancel={endDrag}
      onDoubleClick={(event) => {
        event.stopPropagation();
        onReset();
      }}
      onClick={(event) => event.stopPropagation()}
      onKeyDown={onKeyDown}
      className="group/handle absolute top-0 right-0 z-10 flex h-full w-2 cursor-col-resize touch-none justify-end opacity-0 outline-none select-none group-hover/header:opacity-100 focus-visible:opacity-100"
    >
      <span className="h-full w-0.5 bg-border group-focus-visible/handle:bg-ring" aria-hidden />
    </div>
  );
}

import { useCallback, useMemo, useRef, useState, useSyncExternalStore } from "react";
import {
  type ColumnLimits,
  type ColumnWidths,
  parseStoredWidths,
  resetColumnWidth,
  serializeWidths,
  setColumnWidth,
  widthsStorageKey,
} from "@/ui/data-grid/column-widths";

// Same-tab writes don't fire the `storage` event, so writers notify here too.
const listeners = new Set<() => void>();

function notify() {
  for (const listener of listeners) listener();
}

function subscribe(listener: () => void) {
  listeners.add(listener);
  const onStorage = () => listener();
  window.addEventListener("storage", onStorage);
  return () => {
    listeners.delete(listener);
    window.removeEventListener("storage", onStorage);
  };
}

function readRaw(key: string): string | null {
  try {
    return window.localStorage.getItem(key);
  } catch {
    return null;
  }
}

function writeRaw(key: string, widths: ColumnWidths): boolean {
  try {
    if (Object.keys(widths).length === 0) window.localStorage.removeItem(key);
    else window.localStorage.setItem(key, serializeWidths(widths));
    return true;
  } catch {
    return false;
  }
}

const getServerSnapshot = () => null;

/**
 * Column widths the operator chose for one grid, persisted under
 * `pylon.grid.<storageKey>.v1`. Storage is read through `useSyncExternalStore`
 * so server render and hydration see `{}` and the client then picks up the
 * stored value without a hydration mismatch. `setWidth` only updates local
 * state (live drag); `commit` writes; `reset` writes immediately. When storage
 * is unavailable the widths still apply for this page view.
 */
export function useColumnWidths(
  storageKey: string,
  columns: ColumnLimits[],
): {
  widths: ColumnWidths;
  setWidth(id: string, w: number): void;
  commit(): void;
  reset(id: string): void;
} {
  const key = widthsStorageKey(storageKey);
  const raw = useSyncExternalStore(subscribe, () => readRaw(key), getServerSnapshot);

  const limitsSig = JSON.stringify(columns.map((c) => [c.id, c.minSize, c.maxSize]));
  // Re-parse only when the stored value or the column limits actually change.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const stored = useMemo(() => parseStoredWidths(raw, columns), [raw, limitsSig]);

  // Uncommitted widths (during a drag, or when storage refused the write).
  const [pending, setPending] = useState<ColumnWidths | null>(null);
  const pendingRef = useRef<ColumnWidths | null>(null);

  const limitsById = useMemo(() => {
    const out = new Map<string, ColumnLimits>();
    for (const c of columns) out.set(c.id, c);
    return out;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [limitsSig]);

  const setWidth = useCallback(
    (id: string, w: number) => {
      const limits = limitsById.get(id);
      if (!limits || !Number.isFinite(w)) return;
      const next = setColumnWidth(pendingRef.current ?? stored, id, w, limits);
      pendingRef.current = next;
      setPending(next);
    },
    [limitsById, stored],
  );

  const commit = useCallback(() => {
    const next = pendingRef.current;
    if (!next) return;
    if (writeRaw(key, next)) {
      pendingRef.current = null;
      setPending(null);
      notify();
    }
  }, [key]);

  const reset = useCallback(
    (id: string) => {
      const next = resetColumnWidth(pendingRef.current ?? stored, id);
      if (writeRaw(key, next)) {
        pendingRef.current = null;
        setPending(null);
        notify();
      } else {
        pendingRef.current = next;
        setPending(next);
      }
    },
    [key, stored],
  );

  return { widths: pending ?? stored, setWidth, commit, reset };
}

export type ColumnLimits = { id: string; minSize: number; maxSize: number };
export type ColumnWidths = Record<string, number>;

export function widthsStorageKey(storageKey: string): string {
  return `pylon.grid.${storageKey}.v1`;
}

export function clampWidth(width: number, limits: ColumnLimits): number {
  return Math.min(limits.maxSize, Math.max(limits.minSize, Math.round(width)));
}

export function parseStoredWidths(raw: string | null, columns: ColumnLimits[]): ColumnWidths {
  if (!raw) return {};
  let data: unknown;
  try {
    data = JSON.parse(raw);
  } catch {
    return {};
  }
  if (typeof data !== "object" || data === null || Array.isArray(data)) return {};
  const record = data as Record<string, unknown>;
  const out: ColumnWidths = {};
  for (const col of columns) {
    if (!Object.prototype.hasOwnProperty.call(record, col.id)) continue;
    const value = record[col.id];
    if (typeof value !== "number" || !Number.isFinite(value)) continue;
    out[col.id] = clampWidth(value, col);
  }
  return out;
}

export function setColumnWidth(
  widths: ColumnWidths,
  id: string,
  width: number,
  limits: ColumnLimits,
): ColumnWidths {
  return { ...widths, [id]: clampWidth(width, limits) };
}

export function resetColumnWidth(widths: ColumnWidths, id: string): ColumnWidths {
  const { [id]: _removed, ...rest } = widths;
  return rest;
}

export function serializeWidths(widths: ColumnWidths): string {
  return JSON.stringify(widths);
}

